files.content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', sans-serif;
  font-size: 16px;
  background: #1a1a2e;
  color: #eaeaea;
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  padding: 20px;
}

.board {
  background: #16213e;
  border: 4px solid #0f3460;
  border-radius: 12px;
  padding: 24px;
  max-width: 1100px;
  width: 100%;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.5);
}

h1 {
  font-size: 28px;
  text-align: center;
  margin-bottom: 20px;
  color: #e94560;
  letter-spacing: 2px;
}

.add-form {
  display: flex;
  gap: 12px;
  margin-bottom: 24px;
  flex-wrap: wrap;
}

#card-text {
  flex: 1;
  min-width: 180px;
  padding: 12px 16px;
  font-size: 16px;
  border: 3px solid #0f3460;
  border-radius: 8px;
  background: #1a1a2e;
  color: #eaeaea;
  outline: none;
}

#card-text:focus {
  border-color: #e94560;
  box-shadow: 0 0 0 3px rgba(233, 69, 96, 0.3);
}

button {
  font-family: inherit;
  font-size: 16px;
  font-weight: 600;
  padding: 12px 20px;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s, box-shadow 0.15s;
  background: #e94560;
  color: #fff;
  letter-spacing: 0.5px;
}

button:hover {
  background: #c73650;
  box-shadow: 0 4px 12px rgba(233, 69, 96, 0.4);
}

button:focus-visible {
  outline: 3px solid #eaeaea;
  outline-offset: 2px;
}

button:active {
  transform: scale(0.96);
  background: #a82a40;
}

button:disabled {
  background: #2a2a4a;
  color: #666;
  cursor: not-allowed;
  transform: none;
  box-shadow: none;
}

.columns {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}

@media (max-width: 720px) {
  .columns {
    grid-template-columns: 1fr;
  }
}

.column {
  background: #0f3460;
  border-radius: 10px;
  padding: 16px;
  min-height: 200px;
  display: flex;
  flex-direction: column;
}

.column-title {
  font-size: 20px;
  margin-bottom: 16px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  color: #eaeaea;
}

.count {
  background: #e94560;
  color: #fff;
  font-size: 14px;
  padding: 2px 10px;
  border-radius: 20px;
  min-width: 28px;
  text-align: center;
}

.card-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 12px;
  flex: 1;
}

.card {
  background: #1a1a2e;
  border: 2px solid #e94560;
  border-radius: 8px;
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  word-break: break-word;
}

.card-text {
  font-size: 16px;
  line-height: 1.4;
}

.card-actions {
  display: flex;
  gap: 6px;
  justify-content: flex-end;
}

.card-actions button {
  padding: 6px 10px;
  font-size: 14px;
  min-width: 36px;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

@media (max-width: 400px) {
  .board {
    padding: 16px;
  }
  h1 {
    font-size: 22px;
  }
  .card-actions button {
    padding: 6px 8px;
    font-size: 13px;
  }
}

(function() {
  'use strict';

  const STORAGE_KEY = 'pixel-kanban-cards';
  const columns = ['todo', 'doing', 'done'];
  const columnLabels = { todo: 'To do', doing: 'Doing', done: 'Done' };

  let cards = [];
  let nextId = 1;

  const form = document.getElementById('add-form');
  const input = document.getElementById('card-text');
  const lists = {
    todo: document.getElementById('todo-list'),
    doing: document.getElementById('doing-list'),
    done: document.getElementById('done-list')
  };
  const counts = {
    todo: document.getElementById('todo-count'),
    doing: document.getElementById('doing-count'),
    done: document.getElementById('done-count')
  };

  function load() {
    try {
      const raw = localStorage.getItem(STORAGE_KEY);
      if (raw) {
        const data = JSON.parse(raw);
        cards = data.cards || [];
        nextId = data.nextId || 1;
      }
    } catch (e) {
      cards = [];
      nextId = 1;
    }
  }

  function save() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify({ cards, nextId }));
    } catch (e) {
      // ignore storage errors
    }
  }

  function render() {
    columns.forEach(function(status) {
      lists[status].innerHTML = '';
    });

    cards.forEach(function(card) {
      const li = document.createElement('li');
      li.className = 'card';
      li.dataset.id = card.id;

      const span = document.createElement('span');
      span.className = 'card-text';
      span.textContent = card.text;

      const actions = document.createElement('div');
      actions.className = 'card-actions';

      const idx = columns.indexOf(card.status);

      const leftBtn = document.createElement('button');
      leftBtn.type = 'button';
      leftBtn.textContent = '\u2190';
      leftBtn.setAttribute('aria-label', 'Move card left');
      leftBtn.className = 'move-left';
      leftBtn.disabled = idx === 0;
      leftBtn.addEventListener('click', function() {
        moveCard(card.id, -1);
      });

      const rightBtn = document.createElement('button');
      rightBtn.type = 'button';
      rightBtn.textContent = '\u2192';
      rightBtn.setAttribute('aria-label', 'Move card right');
      rightBtn.className = 'move-right';
      rightBtn.disabled = idx === columns.length - 1;
      rightBtn.addEventListener('click', function() {
        moveCard(card.id, 1);
      });

      const delBtn = document.createElement('button');
      delBtn.type = 'button';
      delBtn.textContent = '\u2715';
      delBtn.setAttribute('aria-label', 'Delete card');
      delBtn.className = 'delete';
      delBtn.addEventListener('click', function() {
        deleteCard(card.id);
      });

      actions.appendChild(leftBtn);
      actions.appendChild(rightBtn);
      actions.appendChild(delBtn);

      li.appendChild(span);
      li.appendChild(actions);

      lists[card.status].appendChild(li);
    });

    updateCounts();
  }

  function updateCounts() {
    columns.forEach(function(status) {
      const count = cards.filter(function(c) { return c.status === status; }).length;
      counts[status].textContent = count;
    });
  }

  function addCard(text) {
    cards.push({
      id: nextId++,
      text: text.trim(),
      status: 'todo'
    });
    save();
    render();
  }

  function moveCard(id, direction) {
    const card = cards.find(function(c) { return c.id === id; });
    if (!card) return;
    const idx = columns.indexOf(card.status);
    const newIdx = idx + direction;
    if (newIdx < 0 || newIdx >= columns.length) return;
    card.status = columns[newIdx];
    save();
    render();
  }

  function deleteCard(id) {
    cards = cards.filter(function(c) { return c.id !== id; });
    save();
    render();
  }

  form.addEventListener('submit', function(e) {
    e.preventDefault();
    const text = input.value.trim();
    if (text) {
      addCard(text);
      input.value = '';
      input.focus();
    }
  });

  load();
  render();
})();
